/**
 * OODA Loop Tracker — tool-local actions.
 *
 * Category: Decision Frameworks / Adaptation Cycles (squad S13, Wave 4)
 * Tool:     Boyd's Observe-Orient-Decide-Act cycle for fast-moving / adversarial
 *           situations. One row per situation; each row carries the four phase
 *           texts and a completion timestamp.
 *
 * Agent surface: tool.ooda_loop.*
 * Backing CRUD : workspace.ooda_cycle.* (auto-generated by defineCrudActions
 *                in src/lib/actions/workspace/index.ts).
 *
 * ─── CRUD-BACKED tool pattern (see daci.ts for the canonical reference) ──
 * OODA cycles are a record-keeping entity — generic create / list / update /
 * delete already exist via the auto-generated workspace.ooda_cycle.* surface.
 * This file only adds VERBS THE AGENT WANTS TO SPEAK in the OODA loop's
 * domain vocabulary — phase-level operations that the generic CRUD surface
 * can't express without the agent constructing a full patch payload:
 *
 *   1. list_state      — read all cycles split into {active, completed} with
 *                        phase-completeness stats (avg phases filled, fully
 *                        documented count, total). Lets the agent answer
 *                        "what's open?" and "which need finishing?" in one
 *                        round-trip.
 *   2. advance_phase   — set one of the four phase texts (observe / orient /
 *                        decide / act) by name. Setting "act" auto-completes
 *                        the cycle (stamps completedAt) — codifies Boyd's
 *                        loop closure: once you've acted, the cycle is done
 *                        and the next observation starts a new cycle.
 *                        Idempotent — setting a phase that already has text
 *                        overwrites it (agents iterate on phrasing).
 *   3. complete_cycle  — manually stamp completedAt without advancing through
 *                        "act". Used when a cycle is abandoned mid-loop
 *                        ("situation resolved itself" / "no longer relevant").
 *                        requiresConfirmation:true because after completion
 *                        advance_phase becomes a no-op on this cycle (we
 *                        intentionally keep completed cycles immutable to
 *                        preserve the historical record).
 *   4. start_cycle     — convenience over workspace.ooda_cycle.create. The
 *                        agent's natural phrasing is "start a cycle for X" —
 *                        this skips the full create payload and returns the
 *                        new id so the agent can immediately advance_phase
 *                        against it.
 *
 * ─── ENTITY KIND ─────────────────────────────────────────────────────────
 * Server kind: "workspace:oodaCycle" (camelCase) — matches
 * kindFromToolId("workspace.ooda_cycle") used by the auto-generated CRUD
 * in src/lib/actions/workspace/index.ts. The browser sync engine registers
 * the same camelCase collection (see registerCollection("oodaCycle",
 * "oodaCycles") in workspace-store.ts), so MCP writes round-trip into the
 * browser store.
 *
 * ─── ID NAMING ──────────────────────────────────────────────────────────
 * Namespace is `tool.ooda_loop` (snake_case; the route is /ooda-loop but
 * registry ids use underscores so the Anthropic dot→underscore munging
 * stays unambiguous).
 * ─────────────────────────────────────────────────────────────────────────
 */

import { z } from "zod";
import { nanoid } from "nanoid";
import { registry } from "../registry";
import { useWorkspaceStore } from "@/lib/stores/workspace-store";
import { serverListEntities, serverGetEntity, serverUpsertEntity } from "../server-store";
import type { OODACycle } from "@/lib/stores/workspace-types";

/** Server-side entity kind. Matches kindFromToolId("workspace.ooda_cycle")
 *  used by the auto-generated CRUD in src/lib/actions/workspace/index.ts,
 *  so reads/writes here line up byte-for-byte with the generic surface and
 *  with the browser sync engine's "workspace:oodaCycle" collection. */
const KIND_OODA = "workspace:oodaCycle";

/** Closed enum of the four OODA phases. Matches the optional string fields
 *  on OODACycle (observe / orient / decide / act) verbatim — Zod rejects
 *  anything else at the boundary. */
const PHASES = ["observe", "orient", "decide", "act"] as const;
const PhaseSchema = z.enum(PHASES);

const ws = () => useWorkspaceStore.getState();

/** Count how many of the four phase slots on a cycle have non-empty text.
 *  Used by list_state for the {avgFilledPhases, fullyDocumentedCycles}
 *  stats. Treats whitespace-only as "not filled" — the on-screen UI
 *  considers those empty too. */
function countFilledPhases(c: OODACycle): number {
  let n = 0;
  for (const p of PHASES) {
    const v = c[p];
    if (typeof v === "string" && v.trim().length > 0) n += 1;
  }
  return n;
}

// ──────── tool.ooda_loop.list_state ────────
// Snapshot + summary stats. The agent's most common opening question for
// the OODA tracker is "what's still in flight, and how well documented
// is it?" — returning items split into {active, completed} AND
// phase-completeness stats in one round-trip avoids two follow-up reduces
// on the agent's end.
registry.register({
  id: "tool.ooda_loop.list_state",
  toolId: "tool.ooda_loop",
  name: "list_state",
  category: "read",
  description:
    "List all OODA cycles, split into {active, completed}. Active = no completedAt set. Includes phase-completeness stats {avgFilledPhases (0-4 across all cycles), fullyDocumentedCycles (count with all 4 phases filled), total}. Use to plan next moves ('which cycles need finishing?').",
  paramsSchema: z.object({}),
  handler: async () => {
    const items = ws().oodaCycles ?? [];
    return summarize(items);
  },
  mcpHandler: async (_params, ctx) => {
    const items = await serverListEntities<OODACycle>(ctx.userId, KIND_OODA);
    return summarize(items);
  },
});

/** Build the {active, completed, avgFilledPhases, fullyDocumentedCycles,
 *  total} response shape. Kept as a single helper so the browser-path and
 *  MCP-path responses are guaranteed identical — drift here would mean an
 *  agent gets different shapes depending on whether it's invoked from chat
 *  or over MCP. */
function summarize(items: OODACycle[]) {
  const active: OODACycle[] = [];
  const completed: OODACycle[] = [];
  let filledTotal = 0;
  let fullyDocumentedCycles = 0;

  for (const c of items) {
    if (c.completedAt) completed.push(c);
    else active.push(c);

    const filled = countFilledPhases(c);
    filledTotal += filled;
    if (filled === 4) fullyDocumentedCycles += 1;
  }

  // avgFilledPhases is across ALL cycles (active + completed) so the
  // agent can spot "lots of cycles, but no one's writing them up". When
  // the workspace is empty, report 0 (not NaN) — the agent should be
  // able to assert numeric properties without a guard.
  const avgFilledPhases = items.length === 0 ? 0 : filledTotal / items.length;

  return {
    total: items.length,
    fullyDocumentedCycles,
    avgFilledPhases,
    active,
    completed,
  };
}

// ──────── tool.ooda_loop.advance_phase ────────
// Set one of the four phase texts by name. The agent's natural phrasing
// is "set the observe phase for cycle X to Y" — the generic update
// surface requires marshalling a full {patch: {observe: ...}} payload
// AND knowing the literal field names. By branching on `phase`, the
// agent can speak in OODA vocabulary and we map to the field internally.
//
// Setting "act" auto-completes the cycle (stamps completedAt) — codifies
// Boyd's loop closure: once you've acted, this cycle is done and the
// next observation starts a NEW cycle. The on-screen client also marks
// completion via a separate button, but the agent-driven happy path is
// "advance to act, done".
//
// Idempotent — setting a phase that already has text overwrites it (the
// agent typically iterates on phrasing as it learns more about the
// situation). Returns {updated: boolean, completed: boolean} so the
// caller can detect (a) missing id (updated:false) and (b) the auto-
// complete side effect (completed:true when "act" was just set on a
// not-yet-completed cycle).
//
// requiresConfirmation:false — phase-level edits are the bread-and-butter
// of an OODA session; confirming each one would be intolerable. The
// destructive transition is COMPLETION (which makes the cycle
// immutable to advance_phase), and that's handled by complete_cycle.
registry.register({
  id: "tool.ooda_loop.advance_phase",
  toolId: "tool.ooda_loop",
  name: "advance_phase",
  category: "write",
  requiresConfirmation: false,
  description:
    "Set the text of one of the four OODA phases (observe | orient | decide | act) on an existing cycle. Setting 'act' auto-completes the cycle (stamps completedAt = now). Idempotent — setting a phase that already has text overwrites it. Returns {updated: false} when the id is unknown. Returns {updated: true, completed: true} when 'act' triggered auto-completion.",
  paramsSchema: z.object({
    id: z.string(),
    phase: PhaseSchema,
    content: z.string().min(1).max(4000),
  }),
  handler: async (params) => {
    const items = ws().oodaCycles ?? [];
    const current = items.find((c) => c.id === params.id);
    if (!current) return { updated: false, completed: false };
    // Auto-completion only fires when "act" is being set AND the cycle
    // is not already completed. A re-set of "act" on a completed cycle
    // is treated as content-only — we don't bump completedAt on every
    // edit because the timestamp should reflect when the cycle CLOSED,
    // not when its act-text was last fiddled with.
    const willAutoComplete = params.phase === "act" && !current.completedAt;
    const next: OODACycle = {
      ...current,
      [params.phase]: params.content,
      ...(willAutoComplete ? { completedAt: new Date().toISOString() } : {}),
    };
    ws().upsertOODACycle(next);
    return { updated: true, completed: willAutoComplete };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<OODACycle>(ctx.userId, KIND_OODA, params.id);
    if (!current) return { updated: false, completed: false };
    const willAutoComplete = params.phase === "act" && !current.completedAt;
    const next: OODACycle = {
      ...current,
      [params.phase]: params.content,
      ...(willAutoComplete ? { completedAt: new Date().toISOString() } : {}),
    };
    await serverUpsertEntity<OODACycle>(ctx.userId, KIND_OODA, next);
    return { updated: true, completed: willAutoComplete };
  },
});

// ──────── tool.ooda_loop.complete_cycle ────────
// Manually stamp completedAt. Used when a cycle is abandoned without
// running through "act" — e.g. "situation resolved itself" or "no longer
// relevant". The on-screen UI exposes this as a separate button (the
// CheckCircle2 icon next to each cycle); this is the agent equivalent.
//
// requiresConfirmation:true — once a cycle has completedAt set, the
// on-screen client styles it as the "done" state and the file header
// documents the intent that the cycle becomes immutable to advance_phase
// (see the willAutoComplete branch above — re-setting "act" on a
// completed cycle no longer re-stamps completedAt). The agent should
// confirm because reversing a completion requires a separate
// workspace.ooda_cycle.update patch clearing completedAt.
//
// completedAt is optional — defaults to "now" because the most common
// shape is "I just decided to close this out". Accepts a past ISO so
// the agent can backdate ("we actually wrapped this yesterday").
registry.register({
  id: "tool.ooda_loop.complete_cycle",
  toolId: "tool.ooda_loop",
  name: "complete_cycle",
  category: "write",
  requiresConfirmation: true,
  description:
    "Manually mark an OODA cycle complete by stamping completedAt (defaults to now). Useful when a cycle is abandoned without running through the 'act' phase. After completion the cycle becomes immutable to advance_phase. Returns {updated: false} when the id is unknown. Reversible via a workspace.ooda_cycle.update patch that clears completedAt.",
  paramsSchema: z.object({
    id: z.string(),
    completedAt: z
      .string()
      .optional()
      .describe("ISO timestamp; defaults to the current time when omitted."),
  }),
  handler: async (params) => {
    const items = ws().oodaCycles ?? [];
    const current = items.find((c) => c.id === params.id);
    if (!current) return { updated: false };
    ws().upsertOODACycle({
      ...current,
      completedAt: params.completedAt ?? new Date().toISOString(),
    });
    return { updated: true };
  },
  mcpHandler: async (params, ctx) => {
    const current = await serverGetEntity<OODACycle>(ctx.userId, KIND_OODA, params.id);
    if (!current) return { updated: false };
    await serverUpsertEntity<OODACycle>(ctx.userId, KIND_OODA, {
      ...current,
      completedAt: params.completedAt ?? new Date().toISOString(),
    });
    return { updated: true };
  },
});

// ──────── tool.ooda_loop.start_cycle ────────
// Convenience over workspace.ooda_cycle.create. The agent's natural
// phrasing is "start an OODA cycle for X situation"; the generic create
// surface requires constructing the full {topic, startedAt} payload AND
// generating an id. start_cycle takes just the topic, generates the id
// with the same `ooda_${nanoid(8)}` prefix the CRUD layer uses (so ids
// are visually consistent across both surfaces), and returns the new id
// so the agent can chain into advance_phase immediately.
//
// requiresConfirmation:false (default-for-write would be true, but a
// fresh cycle with no phase text is trivially reversible via remove —
// the user hasn't lost anything if they want to undo).
registry.register({
  id: "tool.ooda_loop.start_cycle",
  toolId: "tool.ooda_loop",
  name: "start_cycle",
  category: "write",
  requiresConfirmation: false,
  description:
    "Start a new OODA cycle with the given topic. startedAt defaults to now. Returns {id} — chain into advance_phase to fill in the observe/orient/decide/act texts. Convenience over workspace.ooda_cycle.create.",
  paramsSchema: z.object({
    topic: z.string().min(1).max(500),
    startedAt: z
      .string()
      .optional()
      .describe("ISO timestamp; defaults to the current time when omitted."),
  }),
  handler: async (params) => {
    const cycle: OODACycle = {
      id: `ooda_${nanoid(8)}`,
      topic: params.topic,
      startedAt: params.startedAt ?? new Date().toISOString(),
    };
    ws().upsertOODACycle(cycle);
    return { id: cycle.id };
  },
  mcpHandler: async (params, ctx) => {
    const cycle: OODACycle = {
      id: `ooda_${nanoid(8)}`,
      topic: params.topic,
      startedAt: params.startedAt ?? new Date().toISOString(),
    };
    await serverUpsertEntity<OODACycle>(ctx.userId, KIND_OODA, cycle);
    return { id: cycle.id };
  },
});
